if (r > 0.0f) {
    float r2 = r * r;
    float r3 = r2 * r;
    float r4 = r3 * r;
    float r6 = r3 * r3;

    // Pressure force (Spiky gradient)
    float wSpiky = spikyGrad * (h - r) / r3;
    float pressureForce = -4.0f * mass * mass * (pi->pressure + pj->pressure) / (2.0f * std::numeric_limits<float>::epsilon() + r) * wSpiky;
    force += pressureForce * rij;

    // Viscosity force (Spiky Laplacian)
    float wLap = spikyLap * (h - r) / r3;
    float wSpikyDeriv = spikyGrad * (h - 2.0f * r) / r4;
    glm::vec3 vRel = pj->velocity - pi->velocity;
    float viscosityForce = viscosity * wLap * (vRel - (vRel * rij) * wSpikyDeriv / wLap);
    force += viscosityForce;
}
